def parse_nested_parens(paren_string: str) -> List[int]:
    def dfs(s: str, depth: int, max_depth: int) -> int:
        if not s:
            return max_depth
        if s[0] == '(':
            return dfs(s[1:], depth + 1, max(max_depth, depth))
        elif s[0] == ')':
            return dfs(s[1:], depth - 1, max_depth)
        else:
            return dfs(s[1:], depth, max_depth)

    result = []
    for group in paren_string.split():
        if not group:
            result.append(0)
        else:
            result.append(dfs(group, 0, 0))
    return result

