def partition(arr, low, high):
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def quickselect(arr, k):
    low, high = 0, len(arr) - 1
    while True:
        pivot_index = partition(arr, low, high)
        if pivot_index == k:
            return arr[pivot_index]
        elif pivot_index < k:
            low = pivot_index + 1
        else:
            high = pivot_index - 1

def median(l: list):
    if not l:
        return None
    if len(l) == 1:
        return l[0]

    mid = len(l) // 2
    if len(l) % 2 == 1:
        return quickselect(l, mid)
    else:
        return (quickselect(l, mid - 1) + quickselect(l, mid)) / 2.0

