def circular_shift(x, shift):
    x_str = str(x)
    if x == 0:
        return "0"
    n = len(x_str)
    effective_shift = shift % n
    if effective_shift == 0:
        return x_str
    else:
        return x_str[-effective_shift:] + x_str[:-effective_shift]

def fruit_distribution(s, n):
    parts = s.split()
    apples = int(parts[0])
    oranges = int(parts[3])
    return max(0, n - apples - oranges)

def fruit_distribution(s, n):
