def will_it_fly(q, w):
    def is_palindrome(subset):
        return subset == subset[::-1]

    def dfs(index, current_sum, subset):
        if index == len(q):
            return is_palindrome(subset) and current_sum <= w

        # Include the current element in the subset
        include = dfs(index + 1, current_sum + q[index], subset + [q[index]])

        # Exclude the current element from the subset
        exclude = dfs(index + 1, current_sum, subset)

        return include or exclude

    return dfs(0, 0, [])

