def is_simple_power(x, n):
    if x == 1:
        return True
    if n <= 0 or n == 1:
        return False
    log_result = math.log(x, n)
    return abs(log_result - round(log_result)) < 1e-9

def is_simple_power(x, n):
    if x == 1:
        return True
    if n == 1 and x != 1:
        return False
    current = 1
    while current < x:
        current *= n
    return current == x

