def sort_array(array):
    if len(array) <= 1:
        return array[:]

    sorted_array = array[:]
    n = len(sorted_array)
    sum_first_last = sorted_array[0] + sorted_array[n-1]

    if sum_first_last % 2 == 0:
        for i in range(n):
            for j in range(0, n-i-1):
                if sorted_array[j] < sorted_array[j+1]:
                    sorted_array[j], sorted_array[j+1] = sorted_array[j+1], sorted_array[j]
    else:
        for i in range(n):
            for j in range(0, n-i-1):
                if sorted_array[j] > sorted_array[j+1]:
                    sorted_array[j], sorted_array[j+1] = sorted_array[j+1], sorted_array[j]

    return sorted_array

