def check_dict_case(d):
    if not d:
        return False

    lower = upper = None

    for key in d.keys():
        if not isinstance(key, str):
            continue

        if lower is None and upper is None:
            lower = key.islower()
            upper = key.isupper()
        elif (lower and not key.islower()) or (upper and not key.isupper()):
            return False

    return True

