def minPath(grid, k):
    N = len(grid)
    dp = [[['inf'] * (k + 1) for _ in range(N)] for _ in range(N)]

    def dfs(r, c, length):
        if r < 0 or r >= N or c < 0 or c >= N:
            return float('inf')
        if length == k:
            return [grid[r][c]]
        if dp[r][c][length] != 'inf':
            return dp[r][c][length]

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        paths = []
        for dr, dc in directions:
            new_r, new_c = r + dr, c + dc
            path = dfs(new_r, new_c, length + 1)
            if path != float('inf'):
                paths.append([grid[r][c]] + path)

        dp[r][c][length] = min(paths) if paths else float('inf')
        return dp[r][c][length]

    result = float('inf')
    for r in range(N):
        for c in range(N):
            path = dfs(r, c, 0)
            if path != float('inf'):
                result = min(result, path)

    return result

