def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]
    return result

def solve(s):
    if not s:
        return ""

    left, right = 0, len(s) - 1

    while left <= right:
        if s[left].isalpha() and s[right].isalpha():
            s = s[:left] + (s[left].swapcase()) + s[left+1:right] + (s[right].swapcase()) + s[right+1:]
            left += 1
            right -= 1
        elif s[left].isalpha():
            s = s[:left] + (s[left].swapcase()) + s[left+1:]
            left += 1
        elif s[right].isalpha():
            s = s[:right] + (s[right].swapcase()) + s[right+1:]
            right -= 1
        else:
            left += 1
            right -= 1

    return s

